int pciconfig_write(
    unsigned long bus, unsigned long dfn,
    unsigned long off, unsigned long len,
    unsigned char *buf
);

/* Write 4 bytes (0x12345678) to Offset 0x40 on Bus 1, Device 2, Function 0 */
unsigned char val[] = {0x78, 0x56, 0x34, 0x12};
unsigned long bus_id = 0x01;
unsigned long dev_fn = 0x20; /* Device 2, Function 0 */

int status = pciconfig_write(
    bus_id, dev_fn,
    0x40, 4,
    val
);
